<script setup>
import {ref,computed,onMounted,nextTick,onBeforeUnmount} from 'vue'
import {LayoutDashboard,Package,PackagePlus,PackageMinus,ScanLine,Printer,Users,History,ArrowLeftRight,LogOut,Menu,X,Search,Plus,RefreshCw,ShieldCheck,AlertTriangle,Settings,Eye,EyeOff,Camera,FileDown,Check,ChevronDown} from 'lucide-vue-next'
import QRCode from 'qrcode'
import {jsPDF} from 'jspdf'
import {Html5Qrcode} from 'html5-qrcode'
const token=ref(localStorage.getItem('nia_token')||'');const user=ref(null);const loginName=ref(''),password=ref(''),newPassword=ref(''),oldPassword=ref('');const loading=ref(false),error=ref(''),notice=ref('')
const page=ref('dashboard'),drawer=ref(false),products=ref([]),users=ref([]),movements=ref([]),dashboard=ref(null)
const branch=ref(''),filial=ref('all'),search=ref(''),selected=ref(null),scanMode=ref('sale'),scanner=ref(null),scanning=ref(false),scanInput=ref(''),showPassword=ref(false)
const modal=ref(''),productForm=ref({name:'',branch:'Kuzof',brand:'',partNumber:'',notes:''}),stockForm=ref({productId:'',filial:1,type:'receive',quantity:1,destinationFilial:2,note:''}),adminForm=ref({loginName:'',displayName:'',password:''}),labels=ref([]),labelQty=ref(1),labelProduct=ref(null)
const branches=['Kuzof','Motor xodovoy'];const nav=[['dashboard','Bosh sahifa',LayoutDashboard],['products','Mahsulotlar',Package],['receive','Kirim',PackagePlus],['sale','Chiqim',PackageMinus],['transfer','Ko‘chirish',ArrowLeftRight],['scanner','Skaner',ScanLine],['labels','Stikerlar',Printer],['history','Tarix',History],['admins','Adminlar',Users]]
const api=async(path,options={})=>{const res=await fetch('/api'+path,{...options,headers:{'Content-Type':'application/json',...(token.value?{Authorization:'Bearer '+token.value}:{}),...options.headers}});const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.error||'Serverda xatolik yuz berdi');return data}
const send=(path,body,method='POST')=>api(path,{method,body:JSON.stringify(body)})
function alertError(e){error.value=e.message||String(e);setTimeout(()=>error.value='',6000)}
function success(s){notice.value=s;setTimeout(()=>notice.value='',4000)}
async function load(){if(!token.value)return;try{user.value=await api('/auth/me');await refresh()}catch(e){logout();alertError(e)}}
async function refresh(){const [p,d,m]=await Promise.all([api('/products'),api('/dashboard'),api('/movements')]);products.value=p;dashboard.value=d;movements.value=m;if(user.value?.role==='superadmin')users.value=await api('/users')}
async function login(){loading.value=true;try{const d=await send('/auth/login',{loginName:loginName.value,password:password.value});token.value=d.token;localStorage.setItem('nia_token',d.token);user.value=d.user;password.value='';await refresh()}catch(e){alertError(e)}finally{loading.value=false}}
function logout(){stopScanner();token.value='';user.value=null;localStorage.removeItem('nia_token')}
async function changePassword(){try{await send('/auth/password',{currentPassword:oldPassword.value,newPassword:newPassword.value});user.value.mustChangePassword=false;oldPassword.value='';newPassword.value='';success('Parol yangilandi')}catch(e){alertError(e)}}
const filtered=computed(()=>products.value.filter(p=>(!branch.value||p.branch===branch.value)&&(!search.value||[p.name,p.code,p.brand,p.partNumber].join(' ').toLowerCase().includes(search.value.toLowerCase()))))
const stockAt=p=>filial.value==='all'?p.total:(p.stocks||[]).find(s=>s.filial===Number(filial.value))?.quantity||0
function openPage(p){page.value=p;drawer.value=false;if(p==='receive'||p==='sale'||p==='transfer')stockForm.value.type=p==='sale'?'sale':p==='transfer'?'transfer':'receive';if(p!=='scanner')stopScanner()}
function startProduct(){productForm.value={name:'',branch:branch.value||'Kuzof',brand:'',partNumber:'',notes:''};modal.value='product'}
async function saveProduct(){try{const p=await send('/products',productForm.value);modal.value='';await refresh();success('Mahsulot qo‘shildi');printFor(p)}catch(e){alertError(e)}}
function printFor(p){labelProduct.value=p;labelQty.value=1;modal.value='label'}
function stockFor(p,type='sale'){stockForm.value={productId:p._id,filial:filial.value==='all'?1:Number(filial.value),type,quantity:1,destinationFilial:2,note:''};selected.value=p;modal.value='stock'}
async function saveStock(){try{const body={...stockForm.value,quantity:Number(stockForm.value.quantity),filial:Number(stockForm.value.filial),destinationFilial:Number(stockForm.value.destinationFilial)};await send(body.type==='transfer'?'/transfers':'/stock',body);modal.value='';await refresh();success('Ombor qoldig‘i yangilandi')}catch(e){alertError(e)}}
async function createAdmin(){try{await send('/users',adminForm.value);modal.value='';adminForm.value={loginName:'',displayName:'',password:''};await refresh();success('Admin yaratildi')}catch(e){alertError(e)}}
async function resetAdmin(u){const password=prompt(`${u.loginName} uchun yangi vaqtinchalik parol (kamida 10 belgi):`);if(password===null)return;try{await send('/users/'+u.id,{password},'PATCH');success('Parol o‘zgartirildi; admin kirganda yangilaydi')}catch(e){alertError(e)}}
async function toggleAdmin(u){try{await send('/users/'+u.id,{active:!u.active},'PATCH');await refresh()}catch(e){alertError(e)}}
async function qrData(code){return QRCode.toDataURL(code,{margin:2,width:420,errorCorrectionLevel:'M',color:{dark:'#000000',light:'#ffffff'}})}
// STIKER: 40 x 30 mm; A4 sahifada 5 ustun, 9 qator, oraliq 0 mm.
async function exportPdf(items){if(!items.length)return;const doc=new jsPDF({unit:'mm',format:'a4',orientation:'portrait'});const x0=5,y0=13.5,w=40,h=30;let index=0;for(const item of items){const count=Math.min(1000,Number(item.qty)||1);const qr=await qrData(item.product.code);for(let j=0;j<count;j++){if(index&&index%45===0)doc.addPage();const k=index%45,x=x0+(k%5)*w,y=y0+Math.floor(k/5)*h;doc.setDrawColor(170);doc.setLineWidth(.12);doc.rect(x,y,w,h);doc.addImage(qr,'PNG',x+12,y+1,20,20);doc.setTextColor(175);doc.setFont('helvetica','bold');doc.setFontSize(6.2);doc.text('NIA AUTO',x+4,y+24,{angle:90});doc.setTextColor(0);doc.setFont('helvetica','bold');let name=item.product.name; // PDF base font is limited for Unicode; fallback to browser font for uncommon characters.
const safe=name.normalize('NFKD').replace(/[^\x20-\x7E]/g,'?');doc.setFontSize(7);const lines=doc.splitTextToSize(safe,36).slice(0,2);doc.text(lines,x+20,y+24,{align:'center'});index++}}doc.save('NiaAuto_Stikerlar_A4.pdf')}
async function addLabel(){if(!labelProduct.value)return;labels.value.push({product:labelProduct.value,qty:Math.max(1,Number(labelQty.value)||1)});modal.value='';success('Stiker navbatga qo‘shildi')}
async function printSingle(){if(!labelProduct.value)return;await exportPdf([{product:labelProduct.value,qty:Math.max(1,Number(labelQty.value)||1)}])}
async function startScanner(){if(scanning.value)return;await nextTick();try{const s=new Html5Qrcode('camera-reader');scanner.value=s;await s.start({facingMode:'environment'},{fps:10,qrbox:{width:240,height:240}},async code=>{await handleCode(code)});scanning.value=true}catch(e){alertError(new Error('Kamera ochilmadi. Telefonda HTTPS talab qilinadi. '+e.message));try{scanner.value?.clear()}catch{}scanner.value=null}}
async function stopScanner(){const s=scanner.value;scanner.value=null;scanning.value=false;if(s){try{if(s.isScanning)await s.stop();s.clear()}catch{}}}
async function handleCode(code){if(!code)return;await stopScanner();scanInput.value=code;let p=products.value.find(x=>x.code===code.trim());if(!p){try{p=await api('/products/code/'+encodeURIComponent(code.trim()))}catch(e){return alertError(e)}}stockFor(p,scanMode.value)}
const fmt=d=>d?new Date(d).toLocaleString('uz-UZ'):''
onMounted(load);onBeforeUnmount(stopScanner)
</script>
<template>
<div class="app">
  <div v-if="error" class="toast error">{{error}} <button @click="error=''">×</button></div>
  <div v-if="notice" class="toast ok">{{notice}}</div>
  <div v-if="!user" class="login-page"><div class="login-card"><div class="brand-large"><span class="orange-mark">◢◢</span><span><i>Nia Auto</i><small>CAR PARTS</small></span></div><h2>Ombor boshqaruvi</h2><p>Nia Auto tizimiga kirish</p><form @submit.prevent="login"><label>Login nomi</label><input v-model="loginName" required autocomplete="username" placeholder="Login nomi"/><label>Parol</label><div class="password"><input v-model="password" :type="showPassword?'text':'password'" required autocomplete="current-password" placeholder="Parol"/><button type="button" @click="showPassword=!showPassword"><Eye v-if="!showPassword" :size="18"/><EyeOff v-else :size="18"/></button></div><button class="primary wide" :disabled="loading">{{loading?'Kutilmoqda...':'Kirish'}}</button></form><p class="login-foot">Parol unutilsa, Superadminga murojaat qiling.</p></div></div>
  <template v-else>
    <div v-if="user.mustChangePassword" class="overlay"><div class="dialog"><h2>Vaqtinchalik parolni o‘zgartiring</h2><p>Davom etish uchun yangi parol belgilang.</p><form @submit.prevent="changePassword"><label>Hozirgi parol</label><input v-model="oldPassword" type="password" required/><label>Yangi parol (10+ belgi)</label><input v-model="newPassword" type="password" minlength="10" required/><button class="primary wide">Parolni yangilash</button></form><button class="ghost" @click="logout">Chiqish</button></div></div>
    <aside class="sidebar" :class="{open:drawer}"><div class="brand"><span class="orange-mark">◢◢</span><span><i>Nia Auto</i><small>CAR PARTS</small></span></div><nav><button v-for="[key,title,Icon] in nav.filter(x=>x[0]!=='admins'||user.role==='superadmin')" :key="key" :class="{active:page===key}" @click="openPage(key)"><component :is="Icon" :size="19"/>{{title}}</button></nav><div class="side-bottom"><span>{{user.displayName}} · {{user.role}}</span><button @click="logout"><LogOut :size="17"/> Chiqish</button></div></aside>
    <div v-if="drawer" class="shade" @click="drawer=false"></div>
    <div class="main"><header class="topbar"><button class="mobile-only icon-btn" @click="drawer=!drawer"><Menu/></button><div class="top-title">NIA <b>AUTO</b> <span> / {{nav.find(n=>n[0]===page)?.[1]}}</span></div><div class="top-actions"><span class="user-pill"><ShieldCheck :size="17"/> {{user.displayName}}</span><button class="icon-btn" title="Yangilash" @click="refresh"><RefreshCw :size="18"/></button></div></header>
    <main class="content">
      <div class="page-head"><div><h1>{{nav.find(n=>n[0]===page)?.[1]}}</h1><p>{{page==='dashboard'?'Barcha filiallar va yo‘nalishlar nazorati':'Nia Auto · Ombor boshqaruvi'}}</p></div><button v-if="page==='products'" class="primary" @click="startProduct"><Plus :size="17"/> Yangi mahsulot</button></div>
      <template v-if="page==='dashboard'&&dashboard"><div class="stats"><div class="stat"><Package/><small>Mahsulot turlari</small><strong>{{dashboard.products}}</strong></div><div class="stat"><PackagePlus/><small>Ombordagi jami dona</small><strong>{{dashboard.units}}</strong></div><div class="stat"><PackageMinus/><small>Jami sotilgan dona</small><strong>{{dashboard.sales}}</strong></div><div class="stat"><AlertTriangle/><small>Kam qolgan joylar</small><strong>{{dashboard.lowStock}}</strong></div></div><div class="dash-grid"><section class="panel"><h3>Filiallar bo‘yicha qoldiq</h3><div v-for="x in dashboard.byFilial" :key="x.filial" class="bar-line"><span>Filial {{x.filial}}</span><div class="bar-track"><div :style="{width:(dashboard.units?100*x.quantity/dashboard.units:0)+'%'}"></div></div><b>{{x.quantity}}</b></div></section><section class="panel"><h3>Yo‘nalishlar</h3><div v-for="x in dashboard.byBranch" :key="x.branch" class="branch-stat"><span>{{x.branch}}</span><strong>{{x.quantity}}</strong></div></section></div><section class="panel"><h3>So‘nggi amallar</h3><div class="table-wrap"><table><thead><tr><th>Vaqt</th><th>Mahsulot</th><th>Amal</th><th>Filial</th><th>Miqdor</th><th>Admin</th></tr></thead><tbody><tr v-for="m in dashboard.latest" :key="m._id"><td>{{fmt(m.createdAt)}}</td><td>{{m.product?.name}}</td><td><span class="tag">{{m.type}}</span></td><td>{{m.filial}}</td><td>{{m.quantity}}</td><td>{{m.by?.displayName}}</td></tr></tbody></table></div></section></template>
      <template v-if="page==='products'"><div class="filters"><div class="search-box"><Search :size="17"/><input v-model="search" placeholder="Nomi, kod, brend yoki part raqam..."/></div><select v-model="branch"><option value="">Barcha yo‘nalishlar</option><option v-for="b in branches" :key="b">{{b}}</option></select><select v-model="filial"><option value="all">Barcha filiallar</option><option v-for="n in 3" :key="n" :value="String(n)">Filial {{n}}</option></select></div><section class="panel table-wrap"><table><thead><tr><th>Mahsulot</th><th>Yo‘nalish</th><th>Part raqam</th><th>Qoldiq</th><th>Amallar</th></tr></thead><tbody><tr v-for="p in filtered" :key="p._id"><td><b>{{p.name}}</b><small class="sub">{{p.brand}} · {{p.code}}</small></td><td><span class="tag">{{p.branch}}</span></td><td>{{p.partNumber||'—'}}</td><td><b>{{stockAt(p)}}</b><small class="sub">{{p.stocks.map(s=>'F'+s.filial+': '+s.quantity).join(' · ')}}</small></td><td><div class="actions"><button class="small" @click="stockFor(p,'receive')">+ Kirim</button><button class="small" @click="stockFor(p,'sale')">− Chiqim</button><button class="small" @click="printFor(p)"><Printer :size="15"/></button></div></td></tr><tr v-if="!filtered.length"><td colspan="5">Mahsulot topilmadi</td></tr></tbody></table></section></template>
      <template v-if="['receive','sale','transfer'].includes(page)"><section class="panel operation"><h3>{{page==='receive'?'Omborga mahsulot qabul qilish':page==='sale'?'Mahsulotni sotilgan deb belgilash':'Filiallar o‘rtasida ko‘chirish'}}</h3><p>Mahsulotni tanlang yoki QR kod orqali toping.</p><div class="filters"><div class="search-box"><Search :size="17"/><input v-model="search" placeholder="Mahsulotni qidirish..."/></div><button class="primary" @click="scanMode=page==='sale'?'sale':'receive';openPage('scanner')"><ScanLine :size="17"/> Skaner</button></div><div class="product-tiles"><button v-for="p in filtered.slice(0,80)" :key="p._id" @click="stockFor(p,page==='sale'?'sale':page==='transfer'?'transfer':'receive')"><b>{{p.name}}</b><small>{{p.partNumber||p.code}} · {{p.branch}}</small><span>Qoldiq: {{p.total}}</span></button></div></section></template>
      <template v-if="page==='scanner'"><section class="panel scanner-panel"><h3>QR skanerlash</h3><p>Telefon kamerasini QR kodga qarating. Kamera uchun HTTPS talab qilinadi.</p><div class="segmented"><button :class="{chosen:scanMode==='receive'}" @click="scanMode='receive'">Kirim</button><button :class="{chosen:scanMode==='sale'}" @click="scanMode='sale'">Chiqim</button></div><div id="camera-reader"></div><button class="primary wide" v-if="!scanning" @click="startScanner"><Camera :size="18"/> Kamerani ochish</button><button class="secondary wide" v-else @click="stopScanner">Kamerani yopish</button><div class="manual"><input v-model="scanInput" placeholder="QR kodni qo‘lda kiriting yoki USB skaner ishlating" @keyup.enter="handleCode(scanInput)"/><button class="primary" @click="handleCode(scanInput)">Topish</button></div></section></template>
      <template v-if="page==='labels'"><section class="panel"><h3>A4 PDF — 40 × 30 mm</h3><p>5 ustun × 9 qator = 45 stiker. Oraliq 0 mm. Har bir mahsulotga bir xil QR kod.</p><div class="filters"><select v-model="labelProduct"><option :value="null">Mahsulot tanlang</option><option v-for="p in products" :key="p._id" :value="p">{{p.name}} · {{p.code}}</option></select><input type="number" min="1" max="1000" v-model.number="labelQty"/><button class="primary" @click="addLabel">Navbatga qo‘shish</button></div><div v-for="(item,i) in labels" :key="i" class="label-line"><span>{{item.product.name}} × {{item.qty}}</span><button class="small" @click="labels.splice(i,1)">Olib tashlash</button></div><div class="label-footer"><b>Jami: {{labels.reduce((s,x)=>s+x.qty,0)}} stiker / {{Math.ceil(labels.reduce((s,x)=>s+x.qty,0)/45)}} sahifa</b><button class="primary" :disabled="!labels.length" @click="exportPdf(labels)"><FileDown :size="18"/> PDF yuklab olish</button></div></section></template>
      <template v-if="page==='history'"><section class="panel table-wrap"><table><thead><tr><th>Sana</th><th>Mahsulot</th><th>Amal</th><th>Filial</th><th>Miqdor</th><th>Oldin → Keyin</th><th>Admin</th><th>Izoh</th></tr></thead><tbody><tr v-for="m in movements" :key="m._id"><td>{{fmt(m.createdAt)}}</td><td>{{m.product?.name}}</td><td><span class="tag">{{m.type}}</span></td><td>{{m.filial}}</td><td>{{m.quantity}}</td><td>{{m.before}} → {{m.after}}</td><td>{{m.by?.displayName}}</td><td>{{m.note}}</td></tr></tbody></table></section></template>
      <template v-if="page==='admins'&&user.role==='superadmin'"><button class="primary" @click="modal='admin'"><Plus :size="17"/> Yangi admin</button><section class="panel table-wrap"><table><thead><tr><th>Login</th><th>Ism</th><th>Rol</th><th>Holat</th><th>Amallar</th></tr></thead><tbody><tr v-for="u in users" :key="u.id"><td>{{u.loginName}}</td><td>{{u.displayName}}</td><td>{{u.role}}</td><td>{{u.active?'Faol':'Bloklangan'}}</td><td><div class="actions" v-if="u.role!=='superadmin'"><button class="small" @click="resetAdmin(u)">Parolni tiklash</button><button class="small" @click="toggleAdmin(u)">{{u.active?'Bloklash':'Faollashtirish'}}</button></div></td></tr></tbody></table></section></template>
    </main></div>
    <div class="bottom-nav"><button @click="openPage('dashboard')"><LayoutDashboard/><small>Bosh sahifa</small></button><button @click="openPage('receive')"><PackagePlus/><small>Kirim</small></button><button class="scan-tab" @click="openPage('scanner')"><ScanLine/><small>Skaner</small></button><button @click="openPage('sale')"><PackageMinus/><small>Chiqim</small></button><button @click="openPage('products')"><Package/><small>Mahsulotlar</small></button></div>
    <div v-if="modal" class="overlay" @click.self="modal=''" ><div class="dialog"><button class="close" @click="modal=''">×</button>
      <template v-if="modal==='product'"><h2>Yangi mahsulot</h2><form @submit.prevent="saveProduct"><label>Mahsulot nomi *</label><input v-model="productForm.name" required maxlength="160"/><label>Yo‘nalish *</label><select v-model="productForm.branch"><option v-for="b in branches" :key="b">{{b}}</option></select><label>Brend (ixtiyoriy)</label><input v-model="productForm.brand"/><label>Part raqam (tavsiya)</label><input v-model="productForm.partNumber"/><label>Izoh</label><textarea v-model="productForm.notes" rows="2"/><button class="primary wide">Saqlash va QR yaratish</button></form></template>
      <template v-if="modal==='stock'"><h2>{{stockForm.type==='receive'?'Kirim':stockForm.type==='sale'?'Chiqim':'Ko‘chirish'}}</h2><p><b>{{selected?.name}}</b> · {{selected?.code}}</p><form @submit.prevent="saveStock"><label>Filial</label><select v-model.number="stockForm.filial"><option v-for="n in 3" :key="n" :value="n">Filial {{n}}</option></select><template v-if="stockForm.type==='transfer'"><label>Qabul qiluvchi filial</label><select v-model.number="stockForm.destinationFilial"><option v-for="n in 3" :key="n" :value="n" :disabled="n===stockForm.filial">Filial {{n}}</option></select></template><label>Miqdor</label><input type="number" v-model.number="stockForm.quantity" min="1" required/><label>Izoh (ixtiyoriy)</label><input v-model="stockForm.note"/><button class="primary wide">Tasdiqlash</button></form></template>
      <template v-if="modal==='label'"><h2>Stiker chop etish</h2><p>{{labelProduct?.name}} · {{labelProduct?.code}}</p><label>Stikerlar soni</label><input type="number" min="1" max="1000" v-model.number="labelQty"/><div class="dialog-actions"><button class="secondary" @click="addLabel">Navbatga qo‘shish</button><button class="primary" @click="printSingle"><FileDown :size="16"/> A4 PDF</button></div></template>
      <template v-if="modal==='admin'"><h2>Yangi admin</h2><form @submit.prevent="createAdmin"><label>Login nomi</label><input v-model="adminForm.loginName" required pattern="[a-z0-9._-]{3,32}"/><label>Ism</label><input v-model="adminForm.displayName" required/><label>Vaqtinchalik parol (10+ belgi)</label><input v-model="adminForm.password" type="text" minlength="10" required/><button class="primary wide">Admin yaratish</button></form></template>
    </div></div>
  </template>
</div>
</template>
